import { useState, useEffect, useCallback } from "react";
import { Cell, DifficultyConfig, GameStatus } from "./types";
import {
  createBoard,
  openCell,
  toggleFlag,
  revealAllMines,
  checkWin,
  countFlags,
} from "./lib/minesweeper";
import DifficultySelect from "./components/DifficultySelect";
import StatusBar from "./components/StatusBar";
import Board from "./components/Board";
import ResultModal from "./components/ResultModal";

export default function App() {
  const [difficulty, setDifficulty] = useState<DifficultyConfig | null>(null);
  const [board, setBoard] = useState<Cell[][]>([]);
  const [status, setStatus] = useState<GameStatus>("playing");
  const [elapsedTime, setElapsedTime] = useState(0);

  // 게임 시작 / 재시작
  const startGame = useCallback((config: DifficultyConfig) => {
    setDifficulty(config);
    setBoard(createBoard(config));
    setStatus("playing");
    setElapsedTime(0);
  }, []);

  // 타이머: 진행 중일 때만 1초씩 증가
  useEffect(() => {
    if (!difficulty || status !== "playing") return;
    const id = setInterval(() => setElapsedTime((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, [difficulty, status]);

  // 칸 열기
  const handleOpen = (row: number, col: number) => {
    if (status !== "playing") return;
    const cell = board[row][col];
    if (cell.isOpen || cell.isFlagged) return;

    // 지뢰를 밟으면 패배
    if (cell.isMine) {
      setBoard(revealAllMines(board));
      setStatus("lost");
      return;
    }

    const next = openCell(board, row, col);
    setBoard(next);
    if (checkWin(next)) setStatus("won");
  };

  // 깃발 토글
  const handleFlag = (row: number, col: number) => {
    if (status !== "playing") return;
    setBoard(toggleFlag(board, row, col));
  };

  // 난이도 선택 화면
  if (!difficulty) {
    return <DifficultySelect onSelect={startGame} />;
  }

  const minesRemaining = difficulty.mineCount - countFlags(board);

  return (
    <div className="min-h-screen w-full bg-slate-950 relative overflow-hidden flex flex-col items-center justify-center p-6">
      {/* 배경 장식 */}
      <div className="pointer-events-none absolute -top-24 -left-24 w-80 h-80 rounded-full bg-sky-500/10 blur-3xl" />
      <div className="pointer-events-none absolute -bottom-24 -right-24 w-80 h-80 rounded-full bg-rose-500/10 blur-3xl" />

      <div className="relative w-full max-w-fit">
        <StatusBar
          minesRemaining={minesRemaining}
          elapsedTime={elapsedTime}
          onReset={() => startGame(difficulty)}
        />
        <Board
          board={board}
          disabled={status !== "playing"}
          onOpen={handleOpen}
          onFlag={handleFlag}
        />
        <p className="text-center text-slate-500 text-xs mt-4">
          좌클릭: 열기 · 우클릭: 깃발
        </p>
      </div>

      <ResultModal
        status={status}
        elapsedTime={elapsedTime}
        onRestart={() => startGame(difficulty)}
        onHome={() => setDifficulty(null)}
      />
    </div>
  );
}
